// Token Radar client renderer: consumes window.RADAR (offline bundle generated by main.ts).
// Implements sorting, search/category/chain/scope filters, live-token comparison, methodology
// documentation, and a detail drawer with in-page valuation recomputation and farm plans.
(() => {
  'use strict';

  const dataset = window.RADAR;
  if (!dataset) return;

  const stage = document.getElementById('main-stage');
  const ui = {
    tab: 'board',
    query: '',
    category: 'all',
    chain: 'all',
    scope: 'all',
    sortKey: 'implied',
    sortDir: -1,
    activeSlug: null,
  };

  const currencyFmt = new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  });

  const formatUsd = (amount) => {
    if (amount === null || amount === undefined || !Number.isFinite(amount)) return 'n/a';
    if (Math.abs(amount) >= 1e9) return `$${(amount / 1e9).toFixed(2)}B`;
    if (Math.abs(amount) >= 1e6) return `$${(amount / 1e6).toFixed(1)}M`;
    if (Math.abs(amount) >= 1e3) return `$${Math.round(amount / 1e3)}K`;
    return currencyFmt.format(amount);
  };

  const formatDelta = (pct) => {
    if (pct === null || pct === undefined || !Number.isFinite(pct)) return 'n/a';
    return `${pct > 0 ? '+' : ''}${pct.toFixed(2)}%`;
  };

  const formatDuration = (days) => {
    if (days === null || days === undefined) return 'unknown';
    if (days >= 365) return `${(days / 365).toFixed(1)}y`;
    return `${Math.max(0, Math.round(days))}d`;
  };

  function h(tag, props, ...children) {
    const node = document.createElement(tag);
    if (props) {
      for (const [k, v] of Object.entries(props)) {
        if (k === 'class') node.className = v;
        else if (k === 'text') node.textContent = v;
        else if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
        else if (v !== null && v !== undefined) node.setAttribute(k, v);
      }
    }
    for (const child of children.flat()) {
      if (child === null || child === undefined) continue;
      node.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
    }
    return node;
  }

  // Exact browser counterpart of evaluateImpliedValuation in lib/model.ts.
  function recomputeValuation(row) {
    const cfg = dataset.config;
    const rawPct = row.change_7d === null || row.change_7d === undefined ? 0 : row.change_7d;
    const growthPct = Math.min(cfg.momentum_max_pct, Math.max(cfg.momentum_min_pct, rawPct));
    const slope = growthPct >= 0 ? cfg.momentum_pos_weight : cfg.momentum_neg_weight;
    const momentumMult = 1 + (growthPct / 100) * slope;
    const effectiveAge = row.age_days === null || row.age_days === undefined ? cfg.fallback_age_days : row.age_days;
    const boundedAge = Math.min(Math.max(effectiveAge, 0), cfg.maturity_horizon_days);
    const maturityMult = cfg.maturity_base + (boundedAge / cfg.maturity_horizon_days) * cfg.maturity_span;
    const baseUsd = row.tvl_usd * cfg.base_tvl_multiple;
    return {
      baseUsd,
      growthPct,
      momentumMult,
      maturityMult,
      impliedUsd: Math.max(1, Math.round(baseUsd * momentumMult * maturityMult)),
    };
  }

  function capitalTier(tvlUsd) {
    if (tvlUsd >= 1e9) return 250;
    if (tvlUsd >= 250e6) return 150;
    if (tvlUsd >= 50e6) return 100;
    if (tvlUsd >= 15e6) return 75;
    return 50;
  }

  function holdWindow(ageDays) {
    if (ageDays === null) return 45;
    if (ageDays < 90) return 90;
    if (ageDays < 180) return 60;
    if (ageDays < 365) return 45;
    return 30;
  }

  function coreFarmAction(row, commitUsd, chain) {
    const cat = (row.category || '').toLowerCase();
    const nm = row.name;
    if (/lend|cdp|collateral|money market|rist/.test(cat)) {
      return `Deposit $${commitUsd} USDC as collateral in ${nm} on ${chain}, draw a minimal borrow position, and keep healthy collateralization.`;
    }
    if (/dex|yield|leveraged farm|amm/.test(cat)) {
      return `Add $${commitUsd} across a balanced stable liquidity pool on ${nm} (${chain}) and retain the LP position receipt.`;
    }
    if (/bridge/.test(cat)) {
      return `Transfer $${commitUsd} USDC into ${chain} via ${nm}, keep capital active on the destination chain, and bridge back after the window.`;
    }
    if (/staking|restak/.test(cat)) {
      return `Stake $${commitUsd} of native gas or LST collateral through ${nm} on ${chain} and retain the staked token in the same wallet.`;
    }
    if (/perpetual|derivative|leverage/.test(cat)) {
      return `Post $${commitUsd} USDC margin on ${nm} (${chain}), open one low-leverage position, and maintain active open interest.`;
    }
    if (/prediction|betting|market/.test(cat)) {
      return `Allocate $${commitUsd} USDC to ${nm} on ${chain} and take one measured market position with a defined settlement date.`;
    }
    if (/curat|allocat|vault|restaked/.test(cat)) {
      return `Allocate $${commitUsd} in USDC or ETH-pegged assets into a curated ${nm} vault on ${chain} and keep vault shares staked.`;
    }
    if (/stable/.test(cat)) {
      return `Mint or supply $${commitUsd} of ${nm}'s stable asset on ${chain} and route it into the protocol's native savings module.`;
    }
    if (/rwa|tokenized/.test(cat)) {
      return `Subscribe $${commitUsd} into ${nm}'s tokenized yield instrument on ${chain} and hold the receipt continuously.`;
    }
    if (/insurance|risk/.test(cat)) {
      return `Purchase $${commitUsd} of protocol coverage through ${nm} on ${chain} and maintain the policy through maturity.`;
    }
    return `Deploy $${commitUsd} USDC into ${nm}'s core smart contract on ${chain} and record at least one qualifying interaction.`;
  }

  function buildProtocolPlan(row) {
    const commitUsd = capitalTier(row.tvl_usd);
    const holdDays = holdWindow(row.age_days);
    const chain = row.chains && row.chains.length ? row.chains[0] : 'its primary network';
    const initialGas = commitUsd >= 150 ? '~$8' : '~$4';
    const recurringGas = Math.max(8, 2 * Math.round(holdDays / 7));

    return [
      {
        instruction: `Create a dedicated burner wallet isolated from main holdings, fund it with $${commitUsd} USDC plus gas on ${chain}, and back up keys offline.`,
        expense: `$${commitUsd} principal + initial funding gas`,
        duration: '10 minutes',
      },
      {
        instruction: `Verify ${row.name}'s official documentation and contract addresses on ${chain} directly before signing any approval to avoid phishing links.`,
        expense: '$0 (verification only)',
        duration: '15 minutes',
      },
      {
        instruction: coreFarmAction(row, commitUsd, chain),
        expense: `$${commitUsd} committed capital + ${initialGas} gas`,
        duration: '15 minutes',
      },
      {
        instruction: 'Execute one organic weekly transaction (rebalance, compound, borrow/repay, or governance action) so activity spans multiple epochs.',
        expense: `~$2/week gas (~$${recurringGas} total)`,
        duration: `10 min/week over ${holdDays} days`,
      },
      {
        instruction: `Keep capital deployed for the entire ${holdDays}-day qualifying horizon and review ${row.name}'s official points or epoch tracker monthly.`,
        expense: `$${commitUsd} remains deployed (withdraw gas only at exit)`,
        duration: `${holdDays} days total`,
      },
      {
        instruction: 'Monitor snapshot announcements and TGE claim portals via verified channels only; never pay upfront claim fees or expose seed phrases.',
        expense: '$0 monitoring (gas only upon valid claim)',
        duration: '10 minutes per milestone',
      },
      {
        instruction: 'Archive wallet address, tx hashes, entry/exit timestamps, and position size in a portfolio ledger for points verification or clean unwind.',
        expense: '$0 (record keeping)',
        duration: '5 minutes setup',
      },
    ];
  }

  function populateHeaderPills() {
    const dateEl = document.getElementById('badge-date');
    dateEl.textContent = '';
    dateEl.appendChild(h('span', null, 'snapshot ', h('strong', { text: dataset.as_of })));

    const modelEl = document.getElementById('badge-model');
    modelEl.textContent = '';
    modelEl.appendChild(h('span', null, 'model ', h('strong', { text: dataset.config.version })));

    const rowsEl = document.getElementById('badge-rows');
    rowsEl.textContent = '';
    rowsEl.appendChild(h('span', null, h('strong', { text: String(dataset.board_total) }), ' ranked'));
  }

  function renderKpis() {
    const grid = document.getElementById('kpi-grid');
    grid.textContent = '';
    const watchCount = dataset.rows.filter((r) => r.watchlisted).length;
    const earlyCount = dataset.board_total - watchCount;
    const positiveCount = dataset.rows.filter((r) => r.change_7d !== null && r.change_7d > 0).length;

    const cards = [
      {
        featured: true,
        k: 'Aggregate Implied Value',
        v: formatUsd(dataset.aggregate_implied_usd),
        d: `across ${dataset.board_total} pre-token protocols`,
      },
      {
        k: 'Watchlist Coverage',
        v: `${watchCount} / ${dataset.watchlist_total}`,
        d: '100% of floor watchlist ranked',
      },
      {
        k: 'Early Discoveries',
        v: String(earlyCount),
        d: `pre-token under ${formatUsd(dataset.floor_usd)} TVL`,
      },
      {
        k: 'Ranked Board',
        v: String(dataset.board_total),
        d: `from ${dataset.total_universe} tracked protocols`,
      },
      {
        k: '7d Positive Momentum',
        v: String(positiveCount),
        d: 'expanding TVL over last 7 days',
      },
    ];

    for (const c of cards) {
      grid.appendChild(
        h(
          'div',
          { class: `kpi-card${c.featured ? ' featured' : ''}` },
          h('div', { class: 'kpi-label', text: c.k }),
          h('div', { class: 'kpi-val', text: c.v }),
          h('div', { class: 'kpi-sub', text: c.d }),
        ),
      );
    }
  }

  function filteredRows() {
    const needle = ui.query;
    return dataset.rows.filter((r) => {
      if (ui.category !== 'all' && r.category !== ui.category) return false;
      if (ui.chain !== 'all' && !r.chains.includes(ui.chain)) return false;
      if (ui.scope === 'watch' && !r.watchlisted) return false;
      if (ui.scope === 'early' && r.watchlisted) return false;
      if (ui.scope === 'growing' && !(r.change_7d !== null && r.change_7d > 0)) return false;
      if (needle) {
        const hay = `${r.name} ${r.slug} ${r.category || ''} ${r.chains.join(' ')}`.toLowerCase();
        if (!hay.includes(needle)) return false;
      }
      return true;
    });
  }

  function renderFilterBar() {
    const bar = document.getElementById('filter-bar');
    bar.textContent = '';

    const search = h('input', {
      type: 'search',
      class: 'search-input',
      placeholder: 'Filter protocol, category, or chain\u2026',
      value: ui.query,
      oninput: (e) => {
        ui.query = e.target.value.toLowerCase();
        renderBoardView();
      },
    });

    const catSelect = h(
      'select',
      {
        class: 'filter-select',
        'aria-label': 'Filter by category',
        onchange: (e) => {
          ui.category = e.target.value;
          renderBoardView();
        },
      },
      h('option', { value: 'all', text: 'All categories' }),
      dataset.categories.map((c) => h('option', { value: c, text: c, selected: ui.category === c ? '' : null })),
    );

    const chainSelect = h(
      'select',
      {
        class: 'filter-select',
        'aria-label': 'Filter by chain',
        onchange: (e) => {
          ui.chain = e.target.value;
          renderBoardView();
        },
      },
      h('option', { value: 'all', text: 'All chains' }),
      dataset.chains.slice(0, 45).map((c) => h('option', { value: c, text: c, selected: ui.chain === c ? '' : null })),
    );

    const scopes = [
      { id: 'all', text: 'All' },
      { id: 'watch', text: 'Watchlist' },
      { id: 'early', text: 'Early Finds' },
      { id: 'growing', text: 'Growing 7d' },
    ];

    const scopeBtns = scopes.map((s) =>
      h('button', {
        type: 'button',
        class: `scope-btn${ui.scope === s.id ? ' active' : ''}`,
        text: s.text,
        onclick: () => {
          ui.scope = s.id;
          renderFilterBar();
          renderBoardView();
        },
      }),
    );

    bar.append(search, catSelect, chainSelect, ...scopeBtns);
    bar.appendChild(h('span', { class: 'count-note', id: 'visible-count', text: `${filteredRows().length} / ${dataset.board_total} rows` }));
  }

  const TABLE_COLS = [
    { id: 'rank', label: 'Rank' },
    { id: 'name', label: 'Protocol' },
    { id: 'category', label: 'Category', cls: 'hide-mobile' },
    { id: 'tvl', label: 'TVL' },
    { id: 'chg', label: '7d Delta' },
    { id: 'age', label: 'Age', cls: 'hide-mobile' },
    { id: 'implied', label: 'Implied Value' },
  ];

  function sortedRows(list) {
    const dir = ui.sortDir;
    const key = ui.sortKey;
    const extract = (r) => {
      if (key === 'rank') return r.rank;
      if (key === 'name') return r.name.toLowerCase();
      if (key === 'category') return (r.category || '').toLowerCase();
      if (key === 'tvl') return r.tvl_usd;
      if (key === 'chg') return r.change_7d === null ? -Infinity : r.change_7d;
      if (key === 'age') return r.age_days === null ? -1 : r.age_days;
      return r.implied_value_usd;
    };
    return list.slice().sort((a, b) => {
      const va = extract(a);
      const vb = extract(b);
      if (va < vb) return -dir;
      if (va > vb) return dir;
      return a.rank - b.rank;
    });
  }

  function renderBoardView() {
    const rows = sortedRows(filteredRows());
    const topImplied = dataset.rows.reduce((m, r) => Math.max(m, r.implied_value_usd), 1);
    stage.textContent = '';

    const headers = TABLE_COLS.map((col) => {
      const active = ui.sortKey === col.id;
      const arrow = active ? (ui.sortDir === -1 ? ' \u25bc' : ' \u25b2') : '';
      return h('th', {
        scope: 'col',
        class: `sortable${col.cls ? ` ${col.cls}` : ''}`,
        text: `${col.label}${arrow}`,
        onclick: () => {
          if (ui.sortKey === col.id) ui.sortDir = -ui.sortDir;
          else {
            ui.sortKey = col.id;
            ui.sortDir = -1;
          }
          renderBoardView();
        },
      });
    });

    const bodyRows = rows.map((r) => {
      const d = r.change_7d;
      const deltaCls = d === null ? 'delta-flat' : d > 0 ? 'delta-pos' : d < 0 ? 'delta-neg' : 'delta-flat';
      const fillPct = Math.max(2, (100 * r.implied_value_usd) / topImplied).toFixed(1);

      return h(
        'tr',
        { class: 'data-row', onclick: () => openDetailSheet(r.slug) },
        h('td', { class: 'col-rank' }, h('strong', { text: String(r.rank) })),
        h(
          'td',
          { class: 'proto-cell' },
          h(
            'div',
            { class: 'proto-title' },
            r.name,
            r.watchlisted
              ? h('span', { class: 'tag-badge tag-watch', text: 'watchlist' })
              : h('span', { class: 'tag-badge tag-early', text: 'early' }),
          ),
          h('div', { class: 'proto-meta', text: `${r.slug} \u00b7 ${r.chains.slice(0, 3).join(', ')}` }),
        ),
        h('td', { class: 'cat-cell hide-mobile', text: r.category || 'Uncategorized' }),
        h('td', { class: 'mono', text: formatUsd(r.tvl_usd) }),
        h('td', { class: `mono ${deltaCls}`, text: formatDelta(d) }),
        h('td', { class: 'mono hide-mobile', text: formatDuration(r.age_days) }),
        h(
          'td',
          null,
          h(
            'div',
            { class: 'val-meter' },
            h('span', { class: 'val-figure', text: formatUsd(r.implied_value_usd) }),
            h('div', { class: 'val-track' }, h('div', { class: 'val-fill', style: `width:${fillPct}%` })),
          ),
        ),
      );
    });

    stage.appendChild(
      h(
        'div',
        { class: 'table-shell', id: 'board-table' },
        h('table', null, h('thead', null, h('tr', null, headers)), h('tbody', null, bodyRows)),
      ),
    );

    if (!rows.length) {
      stage.appendChild(h('div', { class: 'empty-state', text: 'No protocols match the current filters.' }));
    }

    const counter = document.getElementById('visible-count');
    if (counter) counter.textContent = `${rows.length} / ${dataset.board_total} rows`;
  }

  function renderLiveView() {
    stage.textContent = '';
    const head = ['Protocol', 'Category', 'Chains', 'TVL', 'Market Cap', '7d Delta'].map((label) =>
      h('th', { scope: 'col', text: label }),
    );
    const body = dataset.live.map((r) => {
      const cls = r.change_7d === null ? 'delta-flat' : r.change_7d > 0 ? 'delta-pos' : 'delta-neg';
      return h(
        'tr',
        null,
        h('td', { class: 'proto-cell' }, h('div', { class: 'proto-title', text: r.name }), h('div', { class: 'proto-meta', text: r.slug })),
        h('td', { class: 'cat-cell', text: r.category || 'Uncategorized' }),
        h('td', { class: 'chain-cell', text: r.chains.slice(0, 4).join(', ') }),
        h('td', { class: 'mono', text: formatUsd(r.tvl_usd) }),
        h('td', { class: 'mono', text: formatUsd(r.mcap_usd) }),
        h('td', { class: `mono ${cls}`, text: formatDelta(r.change_7d) }),
      );
    });

    stage.appendChild(
      h('p', {
        class: 'live-intro',
        text: 'Protocols with active trading tokens are excluded from the pre-token ranking and shown separately as market capitalization benchmarks.',
      }),
    );
    stage.appendChild(h('div', { class: 'table-shell' }, h('table', null, h('thead', null, h('tr', null, head)), h('tbody', null, body))));
  }

  function renderMethodologyView() {
    const cfg = dataset.config;
    stage.textContent = '';

    const wrap = h(
      'div',
      { class: 'method-wrap' },
      h(
        'div',
        { class: 'card-block' },
        h('h2', { text: `Valuation Formula (${cfg.version})` }),
        h('p', { text: 'Every pre-token protocol is evaluated deterministically from sealed snapshot metrics without manual overrides:' }),
        h(
          'div',
          { class: 'code-box', style: 'margin-top:12px' },
          `base       = tvl_usd * ${cfg.base_tvl_multiple}\n` +
            `growth     = clamp(change_7d, ${cfg.momentum_min_pct}, ${cfg.momentum_max_pct})\n` +
            `growthMult = 1 + (growth / 100) * (growth >= 0 ? ${cfg.momentum_pos_weight} : ${cfg.momentum_neg_weight})\n` +
            `maturity   = ${cfg.maturity_base} + min(age_days, ${cfg.maturity_horizon_days}) / ${cfg.maturity_horizon_days} * ${cfg.maturity_span}\n` +
            'implied    = max(1, round(base * growthMult * maturity))',
        ),
      ),
      h(
        'div',
        { class: 'card-block' },
        h('h3', { text: 'Model Mechanics & Scope' }),
        h(
          'ul',
          null,
          h('li', null, h('strong', { text: 'Base Multiple (0.22x TVL): ' }), 'Conservative baseline valuation anchored to capital locked.'),
          h('li', null, h('strong', { text: 'Momentum Multiplier: ' }), 'Rewards sustained 7-day inflows (0.5x weight) while penalizing outflows harder (0.9x weight).'),
          h('li', null, h('strong', { text: 'Maturity Curve: ' }), 'Scales from 0.55x at launch up to 1.00x at 3 years without a token (unknown listing dates default to 365 days).'),
          h('li', null, h('strong', { text: 'Coverage: ' }), `Includes all ${dataset.watchlist_total} watchlist protocols above ${formatUsd(dataset.floor_usd)} plus ${dataset.early_total} early pre-token protocols below the floor.`),
        ),
      ),
      h(
        'div',
        { class: 'card-block' },
        h('h3', { text: 'Snapshot Provenance' }),
        h(
          'div',
          { class: 'kv-grid' },
          h('span', { class: 'lbl', text: 'Snapshot date' }),
          h('span', { class: 'mono', text: dataset.as_of }),
          h('span', { class: 'lbl', text: 'Source feed' }),
          h('span', { class: 'mono', text: dataset.source }),
          h('span', { class: 'lbl', text: 'Universe size' }),
          h('span', { class: 'mono', text: `${dataset.total_universe} protocols (>= $5M TVL)` }),
          h('span', { class: 'lbl', text: 'Watchlist floor' }),
          h('span', { class: 'mono', text: formatUsd(dataset.floor_usd) }),
          h('span', { class: 'lbl', text: 'Ranked board' }),
          h('span', { class: 'mono', text: `${dataset.board_total} pre-token rows` }),
        ),
      ),
    );

    stage.appendChild(wrap);
  }

  function closeDetailSheet() {
    const sheet = document.getElementById('detail-sheet');
    if (sheet) {
      sheet.classList.remove('open');
      setTimeout(() => sheet.remove(), 220);
    }
    ui.activeSlug = null;
  }

  function openDetailSheet(slug) {
    const row = dataset.rows.find((r) => r.slug === slug);
    if (!row) return;
    ui.activeSlug = slug;

    const existing = document.getElementById('detail-sheet');
    if (existing) existing.remove();

    const check = recomputeValuation(row);
    const isExact = check.impliedUsd === row.implied_value_usd;
    const plan = buildProtocolPlan(row);
    const commitUsd = capitalTier(row.tvl_usd);
    const holdDays = holdWindow(row.age_days);
    const estGas = Math.max(8, 2 * Math.round(holdDays / 7));
    const deltaCls = row.change_7d > 0 ? 'delta-pos' : row.change_7d < 0 ? 'delta-neg' : '';

    const stepNodes = plan.map((st, idx) =>
      h(
        'div',
        { class: 'plan-step' },
        h('div', { class: 'step-num', text: String(idx + 1) }),
        h(
          'div',
          { style: 'flex:1' },
          h('div', { class: 'step-copy', text: st.instruction }),
          h(
            'div',
            { class: 'step-chips' },
            h('span', { class: 'chip-cost', text: `Cost: ${st.expense}` }),
            h('span', { class: 'chip-time', text: `Time: ${st.duration}` }),
          ),
        ),
      ),
    );

    const sheet = h(
      'aside',
      { class: 'detail-sheet open', id: 'detail-sheet', 'aria-label': `${row.name} details` },
      h(
        'div',
        { class: 'sheet-scroll' },
        h('button', { type: 'button', class: 'close-btn', text: 'Close \u2715', onclick: closeDetailSheet }),
        h(
          'div',
          { class: 'sheet-head' },
          h(
            'h2',
            { style: 'display:inline' },
            row.name,
            row.watchlisted
              ? h('span', { class: 'tag-badge tag-watch', text: 'watchlist' })
              : h('span', { class: 'tag-badge tag-early', text: 'early find' }),
          ),
          h('div', { class: 'sheet-sub', text: `Rank #${row.rank} \u00b7 ${row.slug} \u00b7 ${row.category || 'Uncategorized'}` }),
          h('div', { class: 'sheet-sub', text: `${row.chains.join(', ') || 'Unknown chain'} \u00b7 Status: pre-token (no token recorded)` }),
        ),
        h(
          'div',
          { class: 'metric-pair' },
          h('div', { class: 'metric-box' }, h('div', { class: 'metric-k', text: 'TVL' }), h('div', { class: 'metric-v', text: formatUsd(row.tvl_usd) })),
          h('div', { class: 'metric-box' }, h('div', { class: 'metric-k', text: '7d Change' }), h('div', { class: `metric-v ${deltaCls}`, text: formatDelta(row.change_7d) })),
          h('div', { class: 'metric-box' }, h('div', { class: 'metric-k', text: 'Track Record' }), h('div', { class: 'metric-v', text: formatDuration(row.age_days) })),
          h('div', { class: 'metric-box' }, h('div', { class: 'metric-k', text: 'Listed Date' }), h('div', { class: 'metric-v', text: row.listed_at || 'unknown' })),
        ),
        h(
          'div',
          { class: 'card-block' },
          h('h3', null, 'Implied Launch Valuation \u00b7 ', h('span', { class: 'mono', text: formatUsd(row.implied_value_usd) })),
          h(
            'div',
            { class: 'code-box' },
            `base      ${formatUsd(row.tvl_usd)} * ${dataset.config.base_tvl_multiple} = $${Math.round(check.baseUsd).toLocaleString('en-US')}\n` +
              `momentum  ${formatDelta(check.growthPct)} -> x${check.momentumMult.toFixed(3)}\n` +
              `maturity  ${formatDuration(row.age_days)} -> x${check.maturityMult.toFixed(3)}\n` +
              `implied   = ${formatUsd(check.impliedUsd)}`,
          ),
          h(
            'div',
            { class: 'stat-line' },
            h('span', { class: 'lbl', text: 'Implied value / TVL ratio' }),
            h('span', { class: 'mono', text: `${(row.implied_value_usd / row.tvl_usd).toFixed(3)}x` }),
          ),
          h(
            'div',
            { class: `verify-line${isExact ? '' : ' err'}` },
            h('span', { class: 'verify-dot' }),
            isExact
              ? 'verified in-page: browser recomputation matches board.json exactly'
              : `mismatch detected: ${formatUsd(check.impliedUsd)} vs ${formatUsd(row.implied_value_usd)}`,
          ),
        ),
        h(
          'div',
          { class: 'card-block' },
          h('h3', null, 'Farm Execution Plan', h('span', { class: 'plan-summary', text: `$${commitUsd} \u00b7 ${holdDays}d \u00b7 gas ~$${estGas}` })),
          ...stepNodes,
        ),
      ),
    );

    document.body.appendChild(sheet);
  }

  function switchTab(nextTab) {
    ui.tab = nextTab;
    for (const id of ['board', 'live', 'method']) {
      const btn = document.getElementById(`nav-${id}`);
      const on = id === nextTab;
      btn.classList.toggle('active', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
    }
    document.getElementById('kpi-grid').style.display = nextTab === 'board' ? '' : 'none';
    document.getElementById('filter-bar').style.display = nextTab === 'board' ? '' : 'none';
    if (document.getElementById('detail-sheet')) closeDetailSheet();
    if (nextTab === 'board') renderBoardView();
    else if (nextTab === 'live') renderLiveView();
    else renderMethodologyView();
  }

  document.getElementById('nav-board').addEventListener('click', () => switchTab('board'));
  document.getElementById('nav-live').addEventListener('click', () => switchTab('live'));
  document.getElementById('nav-method').addEventListener('click', () => switchTab('method'));
  document.addEventListener('keydown', (ev) => {
    if (ev.key === 'Escape') closeDetailSheet();
  });

  document.getElementById('footer-disclaimer').textContent =
    `Sealed snapshot ${dataset.as_of} (${dataset.source}) \u00b7 Implied values reflect the deterministic ${dataset.config.version} model only and are not financial advice or token launch guarantees.`;

  populateHeaderPills();
  renderKpis();
  renderFilterBar();
  renderBoardView();
})();
